/**
 * events.js — bitcircus101 event renderer
 * Loads events from events-data.json (generated by CI); without it the list
 * says so and links the calendar page.
 */
(function () {
  "use strict";

  var JSON_URL = "events-data.json";
  var CALENDAR_URL = "https://bitcircus101.de/calendar/";
  var MONTHS = [
    "JAN", "FEB", "M\u00c4R", "APR", "MAI", "JUN",
    "JUL", "AUG", "SEP", "OKT", "NOV", "DEZ",
  ];
  var MONTHS_FULL = [
    "JANUAR", "FEBRUAR", "M\u00c4RZ", "APRIL", "MAI", "JUNI",
    "JULI", "AUGUST", "SEPTEMBER", "OKTOBER", "NOVEMBER", "DEZEMBER",
  ];
  var DAYS = ["SO", "MO", "DI", "MI", "DO", "FR", "SA"];
  // Months unfold until this many cards show. The current month alone left a
  // single card in view at a month's end and folded the next weeks away (1–3
  // cards on 5 of 29 days, measured on the live data in October 2026).
  var OPEN_MIN = 6;

  // State — shareable via the URL query (?tags=…&mit=datenburg&q=…). The hash
  // stays reserved for event anchors (#ev-…), so permalinks and filters compose.
  // `mit` lists the friends' calendars switched on, by source id; the events at
  // bitcircus101 (own + home, see events-core relationOf) are always on. The
  // old `nur=bc` is read and dropped: it asked for what is now the default.
  var PARAM = { TAGS: "tags", WITH: "mit", Q: "q" };
  var state = { tags: [], friends: [], q: "" };
  var allFutureSorted = [];
  var feeds = null; // feeds manifest from events-data.json; null until the JSON has loaded
  var relMap = null; // source name → relation (events-core relationMap); null on pre-field data
  var friendList = []; // the friends' calendars the toolbar offers, {id, name} in config order
  var eventsContainer = null;
  var filterBar = null;
  var eventsToolbar = null;
  var feedDefaults = null; // snapshot of the subscribe buttons' shipped hrefs

  function pad(n) { return n < 10 ? "0" + n : "" + n; }

  // "19:00–22:00" when the source gave an end — the wall's form (kiosk.js
  // timeLabel); an all-day event says so instead of showing no time at all.
  function timeLabel(e) {
    if (!e.time) return "ganzt\u00e4gig";
    if (!e.endTime || e.endTime === e.time) return e.time;
    return e.time + "\u2013" + e.endTime;
  }

  function esc(s) {
    return s
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  // Bare-domain URLs (e.g. "bitcircus101.de") would render as a relative href
  // and 404. Prepend https:// when neither a scheme nor a root-relative path is
  // present. Mirrors the sync-side normalization in sync-events.mjs (5ee7f07).
  function httpUrl(u) {
    if (!u) return u;
    if (u.charAt(0) === "/") return u;
    // Only http(s)://… passes through unchanged. Other scheme://-URLs (ftp:, …)
    // and opaque schemes with no "//" (javascript:, data:, mailto:) both fall to
    // the https:// prepend below, which defuses any executable-href payload.
    var scheme = /^([a-z][\w+.-]*):\/\//i.exec(u);
    if (scheme && /^https?$/i.test(scheme[1])) return u;
    return "https://" + u;
  }

  function relOf(e) {
    return EventsCore.sourceRelation(relMap, e.source);
  }

  function friendOn(name) {
    for (var i = 0; i < friendList.length; i++) {
      if (friendList[i].name === name) return state.friends.indexOf(friendList[i].id) > -1;
    }
    return false;
  }

  // The default view — everything at bitcircus101 — plus the friends' calendars
  // the toolbar switched on.
  function shown(e) {
    return relOf(e) !== "friend" || friendOn(e.source);
  }

  // The data's sources list decides who is a friend (a checkbox) and who is at
  // home. Pre-field data (no relation anywhere) has no friends: everything shows.
  function setSources(sources) {
    relMap = EventsCore.relationMap(sources);
    friendList = [];
    if (relMap && sources) {
      for (var i = 0; i < sources.length; i++) {
        var s = sources[i];
        if (s && s.id && s.name && EventsCore.relationOf(s) === "friend") {
          friendList.push({ id: String(s.id).toLowerCase(), name: s.name });
        }
      }
    }
    // Known ids only, in config order, so identical views serialize to one
    // URL — a stale or mistyped `mit` drops out.
    var wanted = state.friends;
    state.friends = [];
    friendList.forEach(function (f) {
      if (wanted.indexOf(f.id) > -1) state.friends.push(f.id);
    });
  }

  // ── URL state ─────────────────────────────────────────────────────────────

  function parseState() {
    var params = new URLSearchParams(window.location.search);
    var raw = (params.get(PARAM.TAGS) || "").split(",");
    state.tags = [];
    for (var i = 0; i < raw.length; i++) {
      var t = raw[i].trim();
      if (!t) continue;
      if (t.charAt(0) !== "#") t = "#" + t;
      if (state.tags.indexOf(t) === -1) state.tags.push(t);
    }
    var ids = (params.get(PARAM.WITH) || "").split(",");
    state.friends = [];
    for (var j = 0; j < ids.length; j++) {
      var id = ids[j].trim().toLowerCase();
      if (id && state.friends.indexOf(id) === -1) state.friends.push(id);
    }
    state.q = (params.get(PARAM.Q) || "").trim();
  }

  // Fixed key order so identical views always serialize to one URL string.
  function serializeState() {
    var parts = [];
    if (state.tags.length) {
      parts.push(PARAM.TAGS + "=" + state.tags.map(function (t) {
        return encodeURIComponent(t.replace(/^#/, ""));
      }).join(","));
    }
    if (state.friends.length) {
      parts.push(PARAM.WITH + "=" + state.friends.map(encodeURIComponent).join(","));
    }
    if (state.q) parts.push(PARAM.Q + "=" + encodeURIComponent(state.q));
    return parts.length ? "?" + parts.join("&") : "";
  }

  var lastUrl = null;
  function syncUrl() {
    var url = window.location.pathname + serializeState() + window.location.hash;
    if (url === lastUrl) return; // Safari throttles replaceState (~100 calls/30s)
    lastUrl = url;
    window.history.replaceState(null, "", url);
  }

  // ── Search & filtering ───────────────────────────────────────────────────

  // Folded on BOTH sides so "lötkolben" and "loetkolben" hit the same events.
  function foldText(s) {
    return (s || "").toLowerCase()
      .replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss")
      .replace(/\s+/g, " ");
  }

  function haystack(e) {
    if (!e.__hay) {
      e.__hay = foldText(
        e.title + " " + (e.subtitle || "") + " " + (e.description || "") + " " +
        (e.location || "") + " " + (e.tags || []).join(" ")
      );
    }
    return e.__hay;
  }

  function searchTokens() {
    return state.q ? foldText(state.q).split(" ").filter(Boolean) : [];
  }

  function matchesTags(e) {
    if (!state.tags.length) return true;
    return state.tags.some(function (f) { return (e.tags || []).indexOf(f) > -1; });
  }

  function matchesSearch(e, tokens) {
    for (var i = 0; i < tokens.length; i++) {
      if (haystack(e).indexOf(tokens[i]) === -1) return false;
    }
    return true;
  }

  // Friends' calendars applied, no cap — the chip source and the count denominator.
  function pool() {
    return allFutureSorted.filter(shown);
  }

  // Filter BEFORE the 30-cap so tags/search can reach events 31–40 of the
  // loaded window (the old order capped first and made them unreachable).
  function visibleEvents() {
    var tokens = searchTokens();
    return pool().filter(function (e) {
      return matchesTags(e) && matchesSearch(e, tokens);
    }).slice(0, 30);
  }

  // Tags in the URL that no loaded event carries (event passed, typo, …).
  function unknownTags() {
    var known = {};
    pool().forEach(function (e) {
      (e.tags || []).forEach(function (t) { known[t] = true; });
    });
    return state.tags.filter(function (t) { return !known[t]; });
  }

  // DOM removal only — state survives (the old version also cleared the active
  // filters here, which silently wiped tag filters on every source toggle).
  function removeFilterBar() {
    if (filterBar && filterBar.parentNode) {
      filterBar.parentNode.removeChild(filterBar);
    }
    filterBar = null;
  }

  // Mirror `state` into every control — checkbox, search input, chips, resets.
  function applyStateToControls() {
    var boxes = document.querySelectorAll("[data-source]");
    for (var i = 0; i < boxes.length; i++) {
      boxes[i].checked = state.friends.indexOf(boxes[i].getAttribute("data-source")) > -1;
    }
    var input = document.getElementById("events-search");
    if (input && input.value !== state.q && document.activeElement !== input) {
      input.value = state.q;
    }
    var searchClear = document.querySelector(".events-search__clear");
    if (searchClear) searchClear.hidden = !state.q;
    if (filterBar) {
      filterBar.querySelectorAll(".events-filter__tag").forEach(function (b) {
        var on = state.tags.indexOf(b.getAttribute("data-tag")) > -1;
        b.classList.toggle("active", on);
        b.setAttribute("aria-pressed", on ? "true" : "false");
      });
      var clearBtn = filterBar.querySelector(".events-filter__clear");
      if (clearBtn) clearBtn.hidden = !state.tags.length && !state.q;
    }
  }

  // Single entry point after any state change; every handler ends here.
  function refresh(opts) {
    // The toolbar is live before the data is: a keystroke or a toggle during
    // the fetch only updates `state` — renderCards applies it once cards exist.
    if (!eventsContainer) return;
    opts = opts || {};
    if (opts.rebuildChips) {
      removeFilterBar();
      buildChips();
    }
    applyStateToControls();
    renderFilteredCards();
    syncUrl();
    updateFeedScope();
  }

  function removeToolbar() {
    if (eventsToolbar && eventsToolbar.parentNode) {
      eventsToolbar.parentNode.removeChild(eventsToolbar);
    }
    eventsToolbar = null;
  }

  function ensureEventsToolbar(insertBeforeNode) {
    if (eventsToolbar && eventsToolbar.parentNode) return;
    var parent = insertBeforeNode.parentNode;
    eventsToolbar = document.createElement("div");
    eventsToolbar.className = "events-toolbar";
    // Built by JS on purpose, so a dead control never shows when JS fails —
    // and built in init(), BEFORE the fetch, so it is part of the first layout:
    // inserted after the data it pushed the loading list down by its own
    // height, a layout shift on every visit. When the data fails or is empty,
    // removeToolbar() takes it away again.
    // The friends' row carries its legend from the start and gets its boxes
    // once the data names the friends (buildSourceToggles) — inline, on the
    // legend's line, so the list below does not move.
    eventsToolbar.innerHTML =
      '<div class="events-toolbar__row events-toolbar__sources" role="group" aria-labelledby="events-sources-label">' +
      '<span class="events-toolbar__legend" id="events-sources-label">weitere kalender:</span>' +
      "</div>" +
      '<div class="events-toolbar__row events-search">' +
      '<label class="events-search__label" for="events-search">suche:</label>' +
      '<input type="search" id="events-search" class="events-search__input" ' +
      'placeholder="titel, ort, schlagwort \u2026" autocomplete="off" />' +
      '<button type="button" class="events-search__clear" hidden aria-label="Suche l\u00f6schen">\u00d7</button>' +
      '<span class="events-search__count"></span>' +
      "</div>";
    parent.insertBefore(eventsToolbar, insertBeforeNode);

    // One debounce for render AND URL \u2014 also caps replaceState frequency.
    var searchInput = document.getElementById("events-search");
    var searchTimer = null;
    searchInput.addEventListener("input", function () {
      var value = this.value;
      if (searchTimer) clearTimeout(searchTimer);
      searchTimer = setTimeout(function () {
        state.q = value.trim();
        refresh();
      }, 150);
    });
    var searchClear = eventsToolbar.querySelector(".events-search__clear");
    // A keyboard press has no pointerdown, so it reads as "" and keeps the
    // hand-back; only a finger is told apart.
    var clearPointer = "";
    searchClear.addEventListener("pointerdown", function (e) {
      clearPointer = e.pointerType;
    });
    // A touch that slid off fires no click, so the click's reset never ran:
    // a key press starts clean on its own.
    searchClear.addEventListener("keydown", function () {
      clearPointer = "";
    });
    searchClear.addEventListener("click", function () {
      state.q = "";
      refresh();
      // The × hides itself once the query is gone: back to the field. Not
      // after a tap — there focusing the field pops the on-screen keyboard
      // straight back up.
      if (clearPointer !== "touch") searchInput.focus();
      clearPointer = "";
    });
  }

  // One checkbox per friend's calendar, into the row the toolbar reserved.
  // Idempotent: a re-render replaces the boxes. No friends → the row goes.
  function buildSourceToggles() {
    var row = eventsToolbar && eventsToolbar.querySelector(".events-toolbar__sources");
    if (!row) return;
    row.querySelectorAll(".events-toolbar__source").forEach(function (l) {
      row.removeChild(l);
    });
    row.hidden = !friendList.length;
    friendList.forEach(function (f) {
      var label = document.createElement("label");
      label.className = "events-toolbar__label events-toolbar__source";
      label.setAttribute("for", "events-src-" + f.id);
      label.innerHTML =
        '<input type="checkbox" id="events-src-' + esc(f.id) + '" class="events-toolbar__checkbox" ' +
        'data-source="' + esc(f.id) + '" />' +
        "<span>" + esc(f.name) + "</span>";
      row.appendChild(label);
    });
    row.querySelectorAll("[data-source]").forEach(function (cb) {
      cb.addEventListener("change", function () {
        // Read all boxes, in their (config) order — never append the toggled one.
        state.friends = [];
        row.querySelectorAll("[data-source]").forEach(function (b) {
          if (b.checked) state.friends.push(b.getAttribute("data-source"));
        });
        refresh({ rebuildChips: true }); // pool changed \u2192 chip set changes
      });
    });
  }

  // A reset hides the button that was just pressed, or replaces the list it
  // sat in: hand the keyboard on instead of dropping it on <body>.
  function focusFilterStart() {
    var first = document.querySelector(".events-filter__tag") ||
      document.getElementById("events-search");
    if (first) first.focus();
  }

  // Chip source is pool() (pre-cap, post-toggle): stable while typing, changes
  // only on data load or source toggle \u2014 never on a chip click or keystroke.
  function buildChips() {
    var tagSet = {};
    pool().forEach(function (e) {
      (e.tags || []).forEach(function (t) { tagSet[t] = true; });
    });
    var allTags = Object.keys(tagSet).sort();
    if (allTags.length) buildFilterBar(allTags, eventsContainer);
  }

  // ── Card Renderer ─────────────────────────────────────────────────────────

  function renderCards(events, el, sources) {
    eventsContainer = el;
    setSources(sources);
    var now = new Date();
    now.setHours(0, 0, 0, 0);

    allFutureSorted = events
      .filter(function (e) {
        return new Date(e.date + "T23:59:59") >= now;
      })
      .sort(function (a, b) {
        // Date then time, so same-day events run chronologically (all-day first).
        return (a.date + (a.time || "")).localeCompare(b.date + (b.time || ""));
      });

    if (!allFutureSorted.length) {
      removeToolbar();
      removeFilterBar();
      el.innerHTML =
        '<p class="events-empty">Keine kommenden Termine gefunden.</p>' +
        '<p><a href="' + CALENDAR_URL + '" target="_blank" rel="noopener noreferrer">' +
        "Kalender \u00f6ffnen \u2197</a></p>";
      el.removeAttribute("aria-busy");
      return;
    }

    ensureEventsToolbar(el);
    buildSourceToggles();
    refresh({ rebuildChips: true });

    // Anchor-wins: a permalink must always land. If the #ev-\u2026 target got
    // filtered away by URL state — or sits in a friend's calendar that is off —
    // drop the filters and switch every calendar on once, then re-render; the
    // scroll happens in renderFilteredCards. Only for an anchor some loaded
    // card carries: a dead permalink (the event is over) changes nothing.
    var h = window.location.hash;
    var target = h && h.indexOf("#ev-") === 0 ? h.slice(1) : null;
    if (target && !document.getElementById(target) && knownAnchor(target) &&
        (state.tags.length || state.q || state.friends.length < friendList.length)) {
      state.tags = [];
      state.q = "";
      state.friends = friendList.map(function (f) { return f.id; });
      refresh({ rebuildChips: true });
    }
  }

  function knownAnchor(id) {
    for (var i = 0; i < allFutureSorted.length; i++) {
      if (ICSCore.eventAnchor(allFutureSorted[i]) === id) return true;
    }
    return false;
  }

  function buildFilterBar(tags, el) {
    if (!tags.length) return;

    filterBar = document.createElement("div");
    filterBar.className = "events-filter";
    filterBar.setAttribute("role", "group");
    filterBar.setAttribute("aria-label", "Termine nach Schlagwort filtern");

    var html = '<span class="events-filter__label" aria-hidden="true">filter:</span>';
    tags.forEach(function (t) {
      html += '<button type="button" class="events-filter__tag" data-tag="' +
        esc(t) + '" aria-pressed="false">' + esc(t) + "</button>";
    });
    html += '<button type="button" class="events-filter__clear" hidden aria-label="Filter zur\u00fccksetzen">' +
      "\u00d7 reset</button>";
    filterBar.innerHTML = html;

    el.parentNode.insertBefore(filterBar, el);

    var clearBtn = filterBar.querySelector(".events-filter__clear");
    filterBar.querySelectorAll(".events-filter__tag").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var tag = btn.getAttribute("data-tag");
        var idx = state.tags.indexOf(tag);
        if (idx > -1) state.tags.splice(idx, 1);
        else state.tags.push(tag);
        refresh();
      });
    });

    // Reset clears tags AND search (the search field has its own × for q only).
    clearBtn.addEventListener("click", function () {
      state.tags = [];
      state.q = "";
      refresh();
      focusFilterStart();
    });
  }

  function updateCount(shown) {
    var elC = document.querySelector(".events-search__count");
    if (!elC) return;
    // Only shown while a filter or search narrows the list \u2014 silent otherwise.
    elC.textContent = (state.q || state.tags.length)
      ? shown + " / " + pool().length + " termine"
      : "";
  }

  function renderFilteredCards() {
    var el = eventsContainer;
    var filtered = visibleEvents();
    updateCount(filtered.length);

    if (!filtered.length) {
      var unknown = unknownTags();
      var msg;
      if (unknown.length && !state.q) {
        // a tag only a friend's calendar carries looks unknown while that
        // calendar is off — say so before guessing the event is over
        msg = "Unbekanntes Schlagwort: " + esc(unknown.join(", ")) +
          (state.friends.length < friendList.length
            ? " \u2014 im bitcircus101 gerade nicht; vielleicht in einem der weiteren Kalender, oder der Termin ist vorbei."
            : " \u2014 vielleicht ist der Termin schon vorbei.");
      } else if (state.q && state.tags.length) {
        msg = "Keine Treffer f\u00fcr Filter + Suche.";
      } else if (state.q) {
        msg = "Keine Treffer f\u00fcr \u201e" + esc(state.q) + "\u201c.";
      } else if (!state.tags.length) {
        msg = state.friends.length
          ? "Keine bevorstehenden Termine in diesem Ausschnitt."
          : "Keine bevorstehenden Termine im bitcircus101 in diesem Ausschnitt.";
      } else {
        msg = "Keine Treffer f\u00fcr diesen Filter.";
      }
      var canReset = state.tags.length || state.q;
      el.innerHTML =
        '<p class="events-empty">' + msg + "</p>" +
        (canReset
          ? '<p><button type="button" class="events-empty__reset">\u00d7 filter zur\u00fccksetzen</button></p>'
          : '<p><a href="' + CALENDAR_URL + '" target="_blank" rel="noopener noreferrer">' +
            "Kalender \u00f6ffnen \u2197</a></p>");
      var resetBtn = el.querySelector(".events-empty__reset");
      if (resetBtn) {
        resetBtn.addEventListener("click", function () {
          state.tags = [];
          state.q = "";
          refresh();
          focusFilterStart();
        });
      }
      el.removeAttribute("aria-busy");
      return;
    }

    // Group by year-month
    var groups = [];
    var groupMap = {};
    filtered.forEach(function (e) {
      var d = new Date(e.date + "T00:00:00");
      var k = d.getFullYear() + "-" + pad(d.getMonth() + 1);
      if (!groupMap[k]) { groupMap[k] = []; groups.push(k); }
      groupMap[k].push(e);
    });

    var html = "";
    var unfolded = 0; // cards in the months before this one (OPEN_MIN)
    var seenSeries = {}; // series whose full card is out (events-core seriesKey)
    groups.forEach(function (k) {
      var parts = k.split("-");
      var monthName = MONTHS_FULL[+parts[1] - 1];
      var isOpen = unfolded < OPEN_MIN ? " open" : "";
      unfolded += groupMap[k].length;
      html += '<details class="events-month"' + isOpen + '>';
      html +=
        '<summary class="events-month__label">' +
        // the "[ ]" are CSS (::before/::after): the panel's green marker
        '<span class="events-month__title">' + monthName + " " + parts[0] +
        "</span>" +
        '<span class="events-month__chevron" aria-hidden="true"></span>' +
        "</summary>";

      groupMap[k].forEach(function (e) {
        var d = new Date(e.date + "T00:00:00");
        var core = window.EventsCore;
        // Cancelled — rename, don't delete (events-core isCancelledTitle): the
        // card shows the title without the marker, struck through, labelled.
        // e.title itself stays raw: eventAnchor and the RSS deep links read it.
        var cancelled = !!(core && core.isCancelledTitle(e.title));
        var shown = cancelled ? core.stripCancelMarker(e.title) : e.title;
        // A series' later dates (events-core seriesKey) are short: title,
        // time, links. Its first card in the list carries the text, the place
        // and the tags — 13 of the 22 cards in the default view repeated one,
        // 11 with the same text (October 2026). A cancelled date never counts
        // as that first card, so the next real one keeps the text.
        var series = core && core.seriesKey ? core.seriesKey(e) : null;
        var repeat = !!(series && seenSeries[series]);
        if (series && !cancelled) seenSeries[series] = true;
        var typeClass = (e.type ? " event-card--" + e.type : "") +
          (cancelled ? " event-card--cancelled" : "") +
          (repeat ? " event-card--repeat" : "");
        // Shared with the RSS feed's deep-link (ics-core.js) so anchors stay in sync.
        var anchor = ICSCore.eventAnchor(e);

        html += '<article class="event-card' + typeClass +
          '" id="' + anchor + '">';

        // Date column
        html += '<div class="event-card__date">';
        html += '<span class="event-card__day">' + pad(d.getDate()) + "</span>";
        html += '<span class="event-card__month">' + MONTHS[d.getMonth()] + "</span>";
        html += '<span class="event-card__dow">' + DAYS[d.getDay()] + "</span>";
        html += "</div>";

        // Content column
        html += '<div class="event-card__content">';
        html += '<div class="event-card__header">';
        // the badge sits inside the h3, so the outline reads "Lötabend abgesagt"
        html += '<h3 class="event-card__title">' + esc(shown) +
          (cancelled ? ' <span class="event-card__cancelled"><span aria-hidden="true">✕ </span>abgesagt</span>' : "") +
          "</h3>";
        // "Kalender: X" for a home source, "Externer Kalender: X" for a
        // friend's, nothing for ours (events-core sourceBadge).
        var badge = core ? core.sourceBadge(relMap, e.source) : "";
        if (badge) {
          html += '<span class="event-card__source">' + esc(badge) + "</span>";
        }
        html += "</div>";
        if (e.subtitle && !repeat) {
          html += '<p class="event-card__subtitle">' + esc(e.subtitle) + "</p>";
        }
        // Full text lives in the card since the detail pages exist; the list shows
        // a teaser and folds the rest into a native <details> (no state to keep,
        // a #ev-… deep link opens it, see the hash block below). Trailing
        // hashtag-only lines are the tag source, not prose — hidden here.
        var text = core ? core.stripTagLines(e.description) : (e.description || "");
        if (text && !repeat) {
          var teaser = core ? core.truncateDesc(text, 200) : text;
          if (teaser !== text) {
            html += '<details class="event-card__more">' +
              '<summary class="event-card__desc">' +
              '<span class="event-card__teaser">' + esc(teaser) + "</span>" +
              '<span class="event-card__more-label">' +
              '<span class="sr-only">Beschreibung ein- oder ausklappen</span></span>' +
              "</summary>" +
              '<div class="event-card__desc event-card__desc--full">' + esc(text) + "</div>" +
              "</details>";
          } else {
            html += '<p class="event-card__desc event-card__desc--full">' + esc(text) + "</p>";
          }
        }
        if (e.location && !repeat) {
          var osmLoc = encodeURIComponent(e.location);
          html += '<a class="event-card__location" href="' +
            'https://www.openstreetmap.org/search?query=' + osmLoc +
            '" target="_blank" rel="noopener noreferrer" title="Auf Karte anzeigen">' +
            '\u25cb ' + esc(e.location) + "</a>";
        }
        // Meta: time + tags
        html += '<div class="event-card__meta">';
        html += '<span class="event-card__time">' + esc(timeLabel(e)) + "</span>";
        if (e.tags && e.tags.length && !repeat) {
          html += '<span class="event-card__tags">';
          e.tags.forEach(function (t) {
            html += '<span class="event-tag">' + esc(t) + "</span>";
          });
          html += "</span>";
        }
        html += "</div>";
        // Action pills
        // External event URLs (e.g. Kult 41) link directly; a Nextcloud calendar
        // view opens on the event's day (EventsCore.calendarHref)
        var calBase = httpUrl(e.calendarUrl || CALENDAR_URL);
        var calHref = e.eventUrl
          ? httpUrl(e.eventUrl)
          : (core ? core.calendarHref(calBase, e.date) : calBase);
        // "extern", not "link": "\u2190 link" beside it copies this card's own
        // permalink, and two "link" pills pointing opposite ways read as one.
        var calLabel = e.eventUrl ? '\u2192 extern' : '\u2192 kalender';
        var calTitle = e.eventUrl ? 'Auf externer Seite \u00f6ffnen' : 'Im Kalender anzeigen';
        html += '<div class="event-card__actions">';
        html += '<button class="event-action event-action--link" ' +
          'data-href="#' + anchor + '" title="Link kopieren">' +
          '\u2190 link</button>';
        // Own page with the full text \u2014 only the sources with pages get one
        // (EventsCore.hasPages), marked `page` on the card. Relative directory
        // href: serves locally and live alike.
        var hasPage = !!(e.id && e.page);
        if (hasPage) {
          html += '<a class="event-action event-action--details" href="e/' +
            esc(e.id) + '/" title="Alle Details auf eigener Seite">' +
            '\u2192 details</a>';
        }
        // A repeat keeps one way to the details: its page, else the calendar
        // or the event's own link.
        if (!repeat || !hasPage) {
          html += '<a class="event-action event-action--cal" href="' +
            esc(calHref) +
            '" target="_blank" rel="noopener noreferrer" title="' + calTitle + '">' +
            calLabel + '</a>';
        }
        if (e.location && !repeat) {
          var osmQuery = encodeURIComponent(e.location);
          html += '<a class="event-action event-action--map" href="' +
            'https://www.openstreetmap.org/search?query=' + osmQuery +
            '" target="_blank" rel="noopener noreferrer" title="Auf Karte anzeigen">' +
            '\u25cb karte</a>';
        }
        html += "</div>";
        html += "</div>"; // content
        html += "</article>";
      });

      html += "</details>";
    });

    el.innerHTML = html;
    el.removeAttribute("aria-busy");

    // Permalink: copy URL to clipboard on click. Deliberately asymmetric: the
    // clipboard gets a clean, query-free event permalink (anchor-wins makes it
    // always land), while the address bar keeps the current filter query.
    el.querySelectorAll(".event-action--link").forEach(function (btn) {
      btn.addEventListener("click", function (e) {
        e.preventDefault();
        var href = btn.getAttribute("data-href");
        var url = window.location.origin + window.location.pathname + href;
        window.history.replaceState(null, "", href);
        if (!navigator.clipboard || !navigator.clipboard.writeText) return;
        navigator.clipboard.writeText(url).then(function () {
          var orig = btn.innerHTML;
          btn.innerHTML = '<span class="event-action__icon">\u2713</span> kopiert';
          btn.classList.add("event-action--copied");
          setTimeout(function () {
            btn.innerHTML = orig;
            btn.classList.remove("event-action--copied");
          }, 1500);
        }).catch(function () {
          // Clipboard denied (e.g. non-secure context) \u2014 fail silently, URL is in the bar.
        });
      });
    });

    // Scroll to anchor if URL has hash. A permalink must land on an OPEN card:
    // the month group is a <details> that only starts open for the current
    // month, and the description fold is one too — open every <details> on the
    // way up plus the card's own before measuring where to scroll.
    if (window.location.hash) {
      var target = document.getElementById(window.location.hash.slice(1));
      if (target) {
        var node = target;
        while (node && node !== el) {
          if (node.tagName === "DETAILS") node.open = true;
          node = node.parentNode;
        }
        var fold = target.querySelector(".event-card__more");
        if (fold) fold.open = true;
        var calm = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
        target.scrollIntoView({ behavior: calm ? "auto" : "smooth", block: "center" });
      }
    }
  }

  // ── Subscribe box follows the filter ("Filter = Feed") ───────────────────
  // The sync publishes per-tag/per-source feeds and lists them in the `feeds`
  // manifest of events-data.json. With exactly one scope active, the subscribe
  // buttons point at the matching feed; in every other case (no manifest, no
  // match, multi-tag, search active) they keep their shipped targets — never
  // advertise a feed the manifest does not list.

  function snapshotFeedDefaults() {
    if (feedDefaults) return;
    feedDefaults = {};
    var btns = document.querySelectorAll("[data-feed]");
    for (var i = 0; i < btns.length; i++) {
      var b = btns[i];
      feedDefaults[b.getAttribute("data-feed")] = {
        href: b.getAttribute("href"),
        download: b.getAttribute("download"),
      };
    }
  }

  // Exactly one scope, or none: one tag with no friend's calendar on → that
  // tag's feed (tag feeds hold the events at bitcircus101, like the default
  // view); every friend's calendar on and no tag → the all-in-one feed.
  function feedScope() {
    if (!feeds || state.q) return null;
    if (state.tags.length === 1 && !state.friends.length) {
      var key = state.tags[0].toLowerCase(); // manifest tag keys are lowercased
      var entry = feeds.tags && feeds.tags[key];
      return entry ? { entry: entry, label: key } : null;
    }
    var allOn = friendList.length && state.friends.length === friendList.length;
    if (allOn && !state.tags.length && feeds.all && feeds.all.rss) {
      return { entry: feeds.all, label: "alle kalender" };
    }
    return null;
  }

  // No feed of its own: several tags at once, or some but not all of the
  // friends' calendars. A static site cannot combine feeds on demand, and
  // pre-building every combination is not a thing. Rather than let the
  // buttons quietly hand out a feed wider or narrower than the page, list the
  // exact parts the manifest has. Only for a pure case: with a search on top,
  // or tags AND a friend's calendar, every feed would be a lie.
  function splitScopes() {
    if (!feeds || state.q) return null;
    var out = [];
    if (state.friends.length && !state.tags.length && state.friends.length < friendList.length) {
      if (!(feeds.primary && feeds.primary.rss)) return null;
      out.push({ label: "im bitcircus101", rss: feeds.primary.rss });
      var sources = feeds.sources || {};
      for (var i = 0; i < state.friends.length; i++) {
        var s = sources[state.friends[i]]; // manifest sources are keyed by cal.id
        if (s && s.rss) out.push({ label: s.name || state.friends[i], rss: s.rss });
      }
      return out.length > 1 ? out : null;
    }
    if (state.tags.length >= 2 && !state.friends.length) {
      for (var j = 0; j < state.tags.length; j++) {
        var key = state.tags[j].toLowerCase();
        var entry = feeds.tags && feeds.tags[key];
        if (entry && entry.rss) out.push({ label: key, rss: entry.rss });
      }
      return out.length ? out : null;
    }
    return null;
  }

  function updateFeedSplit() {
    var box = document.getElementById("events-feed-split");
    if (!box) return;
    var list = box.querySelector(".events-subscribe__scope-links");
    var scopes = splitScopes();
    if (!scopes) {
      box.hidden = true;
      return;
    }
    while (list.firstChild) list.removeChild(list.firstChild);
    for (var i = 0; i < scopes.length; i++) {
      if (i) list.appendChild(document.createTextNode(" · "));
      var a = document.createElement("a");
      a.setAttribute("href", new URL(scopes[i].rss, window.location.href).pathname);
      a.textContent = scopes[i].label;
      list.appendChild(a);
    }
    box.hidden = false;
  }

  function updateFeedScope() {
    var btns = document.querySelectorAll("[data-feed]");
    if (!btns.length) return;
    snapshotFeedDefaults();

    var scope = feedScope();
    for (var i = 0; i < btns.length; i++) {
      var b = btns[i];
      var kind = b.getAttribute("data-feed"); // webcal | ics | rss
      var def = feedDefaults[kind] || {};
      var path = scope && scope.entry && (kind === "rss" ? scope.entry.rss : scope.entry.ics);
      if (path) {
        // Manifest paths are root-absolute; resolve against the current origin
        // so /events and /events.html behave identically.
        var abs = new URL(path, window.location.href);
        b.setAttribute("href", kind === "webcal" ? "webcal://" + abs.host + abs.pathname : abs.pathname);
        if (kind === "ics") {
          b.setAttribute("download", "bitcircus101-" + path.split("/").pop());
        }
      } else {
        if (def.href) b.setAttribute("href", def.href);
        if (kind === "ics") {
          if (def.download) b.setAttribute("download", def.download);
          else b.removeAttribute("download");
        }
      }
    }

    var note = document.getElementById("events-feed-scope");
    if (note) {
      if (scope) {
        note.querySelector(".events-subscribe__scope-tag").textContent = scope.label;
        note.hidden = false;
      } else {
        note.hidden = true;
      }
    }

    updateFeedSplit();
  }

  // ── Error / Loading ─────────────────────────────────────────────────────

  function renderError(el) {
    removeToolbar();
    removeFilterBar();
    el.innerHTML =
      '<div class="events-fallback">' +
      '<p class="events-fallback__cmd">' +
      "termine laden: " +
      '<span class="events-fallback__err">fehlgeschlagen</span></p>' +
      "<p>Termine direkt ansehen: " +
      '<a href="' + CALENDAR_URL + '" target="_blank" rel="noopener noreferrer">' +
      "Kalender \u00f6ffnen \u2197</a></p></div>";
    el.removeAttribute("aria-busy");
  }

  // ── Last Sync Display ────────────────────────────────────────────────────

  var SYNC_BAR_FILL = 60;   // minutes until bar is full (1 hourly run)
  var SYNC_WARN = 120;      // minutes until "stale" warning (1 run missed)
  var SYNC_OVERDUE = 180;   // minutes until "überfällig" (2 runs missed)

  function syncBar(pct) {
    var total = 10;
    var filled = Math.round(pct * total);
    var empty = total - filled;
    var bar = "";
    for (var i = 0; i < filled; i++) bar += "\u2588";
    for (var i = 0; i < empty; i++) bar += "\u2591";
    return "[" + bar + "]";
  }

  function agoText(mins) {
    if (mins < 1) return "jetzt";
    if (mins < 60) return "vor " + mins + " min";
    if (mins >= 2880) return "vor " + Math.floor(mins / 1440) + " Tagen";
    var h = Math.floor(mins / 60);
    return "vor " + h + " h " + (mins % 60) + " min";
  }

  function showLastSync(sources) {
    var el = document.getElementById("events-last-sync");
    if (!el || !sources || !sources.length) return;

    function render() {
      var now = Date.now();
      var html = "";
      for (var i = 0; i < sources.length; i++) {
        var s = sources[i];
        var isOk = s.status === "ok";
        var isStale = s.status === "stale";
        var hasFetch = s.fetchedAt;

        if ((isOk || isStale) && hasFetch) {
          var elapsed = Math.floor((now - new Date(s.fetchedAt).getTime()) / 60000);
          var pct = Math.min(elapsed / SYNC_BAR_FILL, 1);
          var overdue = elapsed > SYNC_OVERDUE;
          var warning = elapsed > SYNC_WARN;
          var stateClass = overdue ? " sync-source--overdue"
            : (warning || isStale) ? " sync-source--stale" : "";

          html += '<span class="sync-source' + stateClass + '">';
          html += '<span class="sync-source__name">' + esc(s.name) + "</span>";

          // Row 1: Sync freshness
          html += '<span class="sync-source__sync">';
          html += '<span class="sync-source__bar">' + syncBar(pct) + "</span> ";
          html += '<span class="sync-source__ago">' + agoText(elapsed) + "</span>";
          if (overdue) {
            html += ' <span class="sync-source__alert">\u26a0 \u00fcberf\u00e4llig</span>';
          } else if (isStale) {
            html += ' <span class="sync-source__alert" title="' +
              esc(s.error || "Fetch fehlgeschlagen") + '">\u26a0 stale</span>';
          }
          html += "</span>";

          // Row 2: Event stats
          html += '<span class="sync-source__events">';
          html += s.events + " bevorstehende Events";
          // changedAt: when the fetched calendar last differed from the run
          // before (sync-events.mjs, processSource) — null until a change has
          // been seen at all, so the text is simply absent until then.
          if (s.changedAt) {
            var changedMins = Math.floor((now - new Date(s.changedAt).getTime()) / 60000);
            html += " \u00b7 ge\u00e4ndert " + agoText(changedMins);
          }
          html += "</span>";
        } else {
          html += '<span class="sync-source sync-source--offline">';
          html += '<span class="sync-source__name">' + esc(s.name) + "</span>";
          html += '<span class="sync-source__alert">offline' +
            (s.error ? " \u00b7 " + esc(s.error) : "") + '</span>';
        }
        html += "</span>";
      }
      el.innerHTML = html;
    }

    render();
    var intervalId = setInterval(render, 30000);

    // Clean up when navigating away
    document.addEventListener("visibilitychange", function () {
      if (document.hidden) {
        clearInterval(intervalId);
        intervalId = null;
      } else if (!intervalId) {
        render();
        intervalId = setInterval(render, 30000);
      }
    });
  }

  // ── Init ──────────────────────────────────────────────────────────────────

  function init() {
    var el = document.getElementById("events-list");
    if (!el) return;

    // A missing shared module (404, stale cache skew) would otherwise surface as
    // a ReferenceError inside the fetch chain — fail visibly instead.
    if (typeof ICSCore === "undefined" || typeof EventsCore === "undefined" ||
        typeof EventsCore.sourceRelation !== "function") {
      renderError(el);
      return;
    }

    // Read URL state BEFORE the fetch so the very first render already
    // reflects a shared link \u2014 no unfiltered flash.
    parseState();

    el.innerHTML =
      '<p class="events-loading">' +
      '<span class="events-loading__cmd">lade termine</span>' +
      '<span class="events-cursor"> \u2026</span></p>';

    // Toolbar first, data second \u2014 see ensureEventsToolbar. The controls
    // already mirror a shared link's state while the list is still loading.
    ensureEventsToolbar(el);
    applyStateToControls();

    fetch(JSON_URL)
      .then(function (res) {
        if (!res.ok) throw new Error("no json");
        return res.json();
      })
      .then(function (data) {
        var events = data.events;
        var sources = data.sources || null;
        feeds = data.feeds || null;
        if (!events) throw new Error("no events");
        renderCards(events, el, sources);
        if (sources) showLastSync(sources);
      })
      .catch(function () {
        renderError(el);
      });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
